                        //         "orderQty": 200,
                        //         "pool": "Primary",
                        //         "settlCurrency": "USDt",
                        //         "side": "Sell",
                        //         "strategy": "OneWay",
                        //         "symbol": "XBTUSDT",
                        //         "text": "Submitted via API.",
                        //         "timeInForce": "ImmediateOrCancel",
